import java.util.Scanner;

public class CalculoImpuesto {
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);
        System.out.print("Introduce la renta anual (EUR): ");
        double renta = teclado.nextDouble();

        double impuesto = 0;
        double remaining = renta;
        double tipoEfectivo;

        // Tramos progresivos (cada tramo solo grava lo que entra en el)
        if (remaining > 60000) {
            impuesto += (remaining - 60000) * 0.45;
            remaining = 60000;
        }
        if (remaining > 35200) {
            impuesto += (remaining - 35200) * 0.37;
            remaining = 35200;
        }
        if (remaining > 20200) {
            impuesto += (remaining - 20200) * 0.30;
            remaining = 20200;
        }
        if (remaining > 12450) {
            impuesto += (remaining - 12450) * 0.24;
            remaining = 12450;
        }
        impuesto += remaining * 0.19;

        tipoEfectivo = (renta > 0) ? (impuesto / renta) * 100 : 0;

        System.out.printf("Renta: %.2f EUR%n", renta);
        System.out.printf("Impuesto a pagar: %.2f EUR%n", impuesto);
        System.out.printf("Tipo medio efectivo: %.2f%%%n", tipoEfectivo);

        teclado.close();
    }
}

