public class NotasDocumentadas {
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);
        System.out.print("Nota (0-10): ");
        double nota = teclado.nextDouble();

        if (nota < 0 || nota > 10) {
            // Rango invalido: la nota debe estar entre 0 y 10
            // Cubre valores negativos y mayores de 10
            System.out.println("Error: nota fuera de rango.");
        } else if (nota >= 9.5) {
            // MH: notas de 9.5 a 10 (incluidos)
            // Se comprueba primero porque es el rango mas alto
            System.out.println("Matricula de Honor");
        } else if (nota >= 9) {
            // SB: notas de 9.0 a 9.49
            // Solo se alcanza si nota < 9.5
            System.out.println("Sobresaliente");
        } else if (nota >= 7) {
            // N: notas de 7.0 a 8.99
            // Solo se alcanza si nota < 9.0
            System.out.println("Notable");
        } else if (nota >= 5) {
            // A: notas de 5.0 a 6.99
            // Umbral minimo para aprobar
            System.out.println("Aprobado");
        } else if (nota >= 3) {
            // I: notas de 3.0 a 4.99
            // Cerca del aprobado pero no alcanza
            System.out.println("Insuficiente");
        } else {
            // MDF: notas de 0 a 2.99
            // Cubre todos los valores restantes (0 a 2.99)
            System.out.println("Muy deficiente");
        }

        teclado.close();
    }
}

